from collections import deque
(n, m) = map(int, input().split())
g = [[] for _ in range(n)]
graph = [list(map(int, input().split())) for _ in range(m)]
inv = [0] * n
outv = [0] * n
for i in range(m):
	graph[i][0] -= 1
	graph[i][1] -= 1
	inv[graph[i][0]] += 1
	outv[graph[i][1]] += 1
S = set()
for (u, v) in graph:
	if inv[u] > 1 and outv[v] > 1:
		g[u].append(v)
	else:
		S.add((u, v))
for (a, b) in S:
	inv[a] -= 1
	outv[b] -= 1
q = deque()
for i in range(n):
	if outv[i] <= 0:
		q.append(i)
dp = [0] * n
while q:
	node = q.pop()
	for nextNode in g[node]:
		dp[nextNode] = max(dp[nextNode], dp[node] + 1)
		outv[nextNode] -= 1
		if outv[nextNode] == 0:
			q.appendleft(nextNode)
print(max(dp) + 1)
